WITH exploded AS (SELECT id, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, v) SELECT attr_key, CASE WHEN status_code >= 403 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list, COUNT_IF(attr_key = 'version') AS version_events FROM exploded GROUP BY 1, 2 ORDER BY status_code_tier ASC NULLS LAST
